/**
 * High school students only. Returns 201 when anything new was added, 200 when every subject was already yours.
 * @summary Add CAPS subjects
 */
export const enrolInCapsSubjects = async (
  enrolInCapsSubjectsRequest: EnrolInCapsSubjectsRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<EnrolInCapsSubjectsResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<EnrolInCapsSubjectsResponse>(getEnrolInCapsSubjectsUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(enrolInCapsSubjectsRequest),
  });
};

