export const getUpdateMyAssessmentUrl = (id: string) => {
  return `/academics/assessments/${id}`;
};

/**
 * Optional If-Match with the ETag from a previous response; a stale value returns 409.
 * @summary Edit one of your assessments
 */
export const updateMyAssessment = async (
  id: string,
  updateMyAssessmentRequest: UpdateMyAssessmentRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<AssessmentView> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<AssessmentView>(getUpdateMyAssessmentUrl(id), {
    ...options,
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(updateMyAssessmentRequest),
  });
};

